//! D77: automatic heading and caption numbers generated by layout.

mod common;

use common::{document, engine, metrics, paragraph};
use soma_doc::block::{Cell, Column, Figure, Heading, Row, Table};
use soma_doc::inline::Image;
use soma_doc::meta::ImageRef;
use soma_doc::node::NodeMeta;
use soma_doc::{Block, CellAlign, Document, Inline, Text};
use soma_layout::{layout, BoxKind, PagedLayout, TextSource};
use soma_template::{parse_template, resolve};

fn text(value: &str) -> Inline {
    Text::new(NodeMeta::synthesized(), value).into()
}

fn heading(level: u8, value: &str) -> Block {
    Block::Heading(Heading::new(
        NodeMeta::synthesized(),
        level,
        vec![text(value)],
    ))
}

fn table(caption: &str) -> Block {
    let columns = vec![Column::new(NodeMeta::synthesized(), CellAlign::Left)];
    let row = Row::new(
        NodeMeta::synthesized(),
        false,
        vec![Cell::new(NodeMeta::synthesized(), vec![paragraph("单元")])],
    );
    let mut table = Table::new(NodeMeta::synthesized(), columns, vec![row]);
    table.caption = vec![text(caption)];
    Block::Table(table)
}

fn figure(caption: &str) -> Block {
    let mut figure = Figure::new(
        NodeMeta::synthesized(),
        Image::new(
            NodeMeta::synthesized(),
            ImageRef::new("figure.png").with_intrinsic(40, 20),
        ),
    );
    figure.caption = vec![text(caption)];
    Block::Figure(figure)
}

const BASE: &str = r#"
name: numbering
page:
  size: custom
  width: 160mm
  height: 240mm
  margin: 10mm
styles:
  - selector:
      element: document
    declarations:
      font-size: 10.5pt
      line-height: 1.6
      align: justify
  - selector:
      element: paragraph
    declarations:
      first-indent: 0
  - selector:
      element: heading
    declarations:
      font-size: 14pt
      space-before: 0.6em
  - selector:
      element: toc
    declarations:
      font-size: 9pt
"#;

fn build(blocks: Vec<Block>, extra: &str) -> PagedLayout {
    let doc: Document = document(blocks);
    let template = format!("{BASE}{extra}");
    let styled = resolve(&doc, &parse_template(&template).expect("template")).expect("styles");
    layout(&doc, &styled, &metrics(), &engine()).expect("layout")
}

fn block_text(layout: &PagedLayout, block: &soma_layout::PlacedBlock) -> String {
    let mut out = String::new();
    for placed in &block.lines {
        for atom in &placed.line.boxes {
            out.push_str(layout.text.atom_text(block.node, atom.atom));
        }
    }
    out
}

fn page_text(layout: &PagedLayout, index: usize) -> String {
    layout.pages[index]
        .blocks
        .iter()
        .map(|block| block_text(layout, block))
        .collect::<Vec<_>>()
        .join(" ")
}

fn all_text(layout: &PagedLayout) -> String {
    (0..layout.pages.len())
        .map(|index| page_text(layout, index))
        .collect::<Vec<_>>()
        .join(" ")
}

#[test]
fn chinese_chapter_numbering_walks_three_levels() {
    let blocks = vec![
        heading(1, "绪论"),
        heading(2, "背景"),
        heading(3, "问题"),
        heading(2, "方法"),
        heading(1, "结论"),
    ];
    let layout = build(
        blocks,
        "numbering:\n  headings: chinese-chapter\n  depth: 3\n",
    );
    let text = all_text(&layout);

    assert!(text.contains("第一章绪论"), "{text}");
    assert!(text.contains("第一节背景"), "{text}");
    assert!(text.contains("一、问题"), "{text}");
    assert!(text.contains("第二节方法"), "{text}");
    assert!(text.contains("第二章结论"), "{text}");
}

#[test]
fn arabic_dotted_numbering_joins_counters() {
    let blocks = vec![
        heading(1, "绪论"),
        heading(2, "背景"),
        heading(3, "问题"),
        heading(2, "方法"),
    ];
    let layout = build(
        blocks,
        "numbering:\n  headings: arabic-dotted\n  depth: 3\n",
    );
    let text = all_text(&layout);

    assert!(text.contains("1绪论"), "{text}");
    assert!(text.contains("1.1背景"), "{text}");
    assert!(text.contains("1.1.1问题"), "{text}");
    assert!(text.contains("1.2方法"), "{text}");
}

#[test]
fn depth_limits_which_headings_get_numbers() {
    let blocks = vec![heading(1, "绪论"), heading(2, "背景"), heading(3, "问题")];
    let layout = build(
        blocks,
        "numbering:\n  headings: arabic-dotted\n  depth: 1\n",
    );
    let text = all_text(&layout);

    assert!(text.contains("1绪论"), "{text}");
    assert!(text.contains("背景"), "{text}");
    assert!(!text.contains("1.1背景"), "{text}");
    assert!(
        text.contains("问题"),
        "level 3 keeps its plain text: {text}"
    );
}

#[test]
fn figures_and_tables_take_their_own_counters() {
    let blocks = vec![
        figure("架构"),
        paragraph("正文。"),
        figure("流程"),
        table("参数"),
        table("结果"),
    ];
    let layout = build(
        blocks,
        "numbering:\n  headings: none\n  figures: \"图 {n}\"\n  tables: \"表 {n}\"\n",
    );
    let text = all_text(&layout);

    assert!(text.contains("图1架构"), "{text}");
    assert!(text.contains("图2流程"), "{text}");
    assert!(text.contains("表1参数"), "{text}");
    assert!(text.contains("表2结果"), "{text}");
}

#[test]
fn captions_are_captured_as_boxes_after_the_contents() {
    let blocks = vec![
        heading(1, "绪论"),
        paragraph("正文。"),
        figure("架构"),
        table("参数"),
    ];
    let layout = build(
        blocks,
        "toc:\n  depth: 1\n  title: 目录\n  leaders: false\n  figures: 图目录\n  tables: 表目录\nnumbering:\n  headings: chinese-chapter\n  figures: \"图 {n}\"\n  tables: \"表 {n}\"\n",
    );
    let report = layout.toc.as_ref().expect("toc report");

    assert_eq!(report.entries, 1, "one chapter");
    assert_eq!(report.figures, 1, "one figure list entry");
    assert_eq!(report.tables, 1, "one table list entry");
    let text = page_text(&layout, 0);
    assert!(text.contains("目录"), "{text}");
    // TOC rows are single object runs, so the number gap is a literal space.
    assert!(
        text.contains("第一章 绪论"),
        "TOC entry carries the number: {text}"
    );
    assert!(text.contains("图目录"), "{text}");
    assert!(text.contains("图 1 架构"), "{text}");
    assert!(text.contains("表目录"), "{text}");
    assert!(text.contains("表 1 参数"), "{text}");
}

#[test]
fn a_document_without_numbering_keeps_plain_headings() {
    let blocks = vec![heading(1, "绪论"), heading(2, "背景")];
    let layout = build(blocks, "");
    let text = all_text(&layout);

    assert!(text.contains("绪论"), "{text}");
    assert!(!text.contains("第一章"), "{text}");
    assert!(!text.contains("1绪论"), "{text}");
}

#[test]
fn caption_numbering_ignores_captionless_figures() {
    let mut plain = Figure::new(
        NodeMeta::synthesized(),
        Image::new(
            NodeMeta::synthesized(),
            ImageRef::new("plain.png").with_intrinsic(40, 20),
        ),
    );
    plain.caption = Vec::new();
    let blocks = vec![Block::Figure(plain), figure("有题注")];
    let layout = build(
        blocks,
        "numbering:\n  headings: none\n  figures: \"图 {n}\"\n",
    );
    let text = all_text(&layout);

    assert!(text.contains("图1有题注"), "{text}");
    assert!(!text.contains("图2"), "{text}");
}

#[test]
fn caption_nodes_are_indexed_for_block_text_queries() {
    // Regression guard: generated caption rows reuse the caption's first node
    // id, so `atom_text` must resolve the numbered text under it.
    let blocks = vec![figure("架构")];
    let layout = build(
        blocks,
        "numbering:\n  headings: none\n  figures: \"图 {n}\"\n",
    );
    let caption = layout.pages[0]
        .blocks
        .iter()
        .find(|block| block.kind == BoxKind::Paragraph)
        .expect("caption block");
    let text = block_text(&layout, caption);

    assert!(text.starts_with("图1"), "{text}");
}
